  (1501, 'diplomat', 'noun', 'c1', '7.0 - 8.0+', '/ˈdɪpləmæt/', '/ˈdɪpləmæt/', '@diplomatist', 'a person whose job is to represent his or her country in a foreign country, for example, in an embassy', 'Washington''s top diplomat in Havana', 'Nhà ngoại giao hàng đầu của Washington ở Havana', ARRAY['diplomat in Havana']::text[], ARRAY['diplomatist', 'official', 'functionary', 'mediator']::text[], '{}'::text[], '{"adjective": "diplomatic"}'::jsonb, 'diplomat_uk.mp3', 'diplomat_us.mp3', 'Global Issues & International Conflicts', 'International Relations & Aid'),
  (1502, 'diplomatic', 'adjective', 'c1', '7.0 - 8.0+', '/ˌdɪpləˈmætɪk/', '/ˌdɪpləˈmætɪk/', 'có tính cách ngoại giao', 'connected with managing relations between countries (= diplomacy)', 'a diplomatic crisis', 'một cuộc khủng hoảng ngoại giao', ARRAY['diplomatic crisis']::text[], ARRAY['negotiation', 'dialogue', 'talks', 'diplomatical']::text[], ARRAY['undiplomatic']::text[], '{"noun": "diplomat"}'::jsonb, 'diplomatic_uk.mp3', 'diplomatic_us.mp3', 'Global Issues & International Conflicts', 'International Relations & Aid'),
  (1503, 'direct', 'adjective', 'a2', '4.0 - 4.5', '/dəˈrekt/', '/dəˈrekt/', 'trực tiếp, chẳng có gì hoặc không có người nào ở giữa', 'going in the straightest line between two places without stopping or changing direction', 'the most direct route', 'con đường trực tiếp nhất', ARRAY['direct route']::text[], ARRAY['guide', 'steer', 'lead']::text[], ARRAY['indirect']::text[], '{"noun": "direction", "adverb": "directly"}'::jsonb, 'direct_uk.mp3', 'direct_us.mp3', 'Travel, Tourism & Transportation', 'Journeys & Directions'),
  (1504, 'direct', 'adverb', 'b1', '5.0 - 5.5', '/dəˈrekt/', '/dəˈrekt/', 'trực tiếp, chẳng có gì hoặc không có người nào ở giữa', 'without stopping or changing direction or vehicle', 'direct to something, We flew direct to Hong Kong.', 'trực tiếp đến một cái gì đó, Chúng tôi đã bay thẳng đến Hồng Kông.', ARRAY['direct to something', 'direct to Hong Kong']::text[], ARRAY['guide', 'steer', 'lead']::text[], ARRAY['indirect']::text[], '{"noun": "direction"}'::jsonb, 'direct_uk.mp3', 'direct_us.mp3', 'Travel, Tourism & Transportation', 'Vehicles & Transit'),
