  (1507, 'directly', 'adverb', 'b1', '5.0 - 5.5', '/dəˈrektli/', '/dəˈrektli/', 'theo đường thẳng hoặc trực tiếp, thẳng thắn', 'without stopping or changing direction', 'The path leads directly to the river.', 'Con đường dẫn thẳng ra sông.', ARRAY['directly to the river']::text[], ARRAY['straight', 'direct', 'immediately', 'instantly']::text[], ARRAY['indirectly']::text[], '{"adjective": "direct", "verb": "direct", "noun": "direction"}'::jsonb, 'directly_uk.mp3', 'directly_us.mp3', 'Travel, Tourism & Transportation', 'Journeys & Directions'),
