  (1509, 'directory', 'noun', 'c1', '7.0 - 8.0+', '/dəˈrektəri/', '/dəˈrektəri/', '(tin học) thư mục', 'a book or electronic resource containing lists of information, usually in alphabetical order, for example people’s phone numbers or the names and addresses of businesses in a particular area', 'a telephone/trade directory', 'danh bạ điện thoại/thương mại', ARRAY['a telephone/trade']::text[], ARRAY['reference', 'list', 'listing']::text[], '{}'::text[], '{"adjective": "direct", "adverb": "direct", "verb": "direct"}'::jsonb, 'directory_uk.mp3', 'directory_us.mp3', 'Food, Cooking & Hospitality', 'Dining & Hospitality'),
  (1510, 'dirt', 'noun', 'b1', '5.0 - 5.5', '/dɜːt/', '/dɜːrt/', 'vật chất không sạch (bụi, đất, bùn chẳng hạn), nhất là khi nó bám vào những nơi ta khôn ...', 'any substance that makes something dirty, for example dust, soil or mud', 'His clothes were covered in dirt.', 'Quần áo của anh ta dính đầy bụi bẩn.', '{}'::text[], ARRAY['ungraded', 'unimproved', 'soil', 'earth']::text[], '{}'::text[], '{"adjective": "dirty"}'::jsonb, 'dirt_uk.mp3', 'dirt_us.mp3', 'Housing, Architecture & Daily Life', 'Household Items & Chores'),
  (1511, 'dirty', 'adjective', 'a1', '3.0 - 3.5', '/ˈdɜːti/', '/ˈdɜːrti/', 'bẩn thỉu, dơ bẩn, dơ dáy, cáu ghét, cáu bẩn, đầy bùn bẩn', 'not clean', 'dirty hands/clothes/dishes', 'tay/quần áo/bát đĩa bẩn', ARRAY['dirty hands/clothes', 'dirty hands']::text[], ARRAY['soiled', 'filthy', 'grimy']::text[], ARRAY['clean']::text[], '{"noun": "dirt"}'::jsonb, 'dirty_uk.mp3', 'dirty_us.mp3', 'Housing, Architecture & Daily Life', 'Household Items & Chores'),
  (1512, 'disability', 'noun', 'b2', '6.0 - 6.5', '/ˌdɪsəˈbɪləti/', '/ˌdɪsəˈbɪləti/', 'sự bất tài, sự bất lực', 'a physical or mental condition that makes it difficult for somebody to do some things that most other people can do', 'a physical/developmental/intellectual disability', 'khuyết tật về thể chất/phát triển/trí tuệ', ARRAY['a physical/developmental']::text[], ARRAY['disablement', 'handicap', 'impairment', 'unfitness']::text[], '{}'::text[], '{"adjective": "disabled", "verb": "disagree"}'::jsonb, 'disability_uk.mp3', 'disability_us.mp3', 'Health, Medicine & Diet', 'Healthcare System'),
  (1513, 'disabled', 'adjective', 'b2', '6.0 - 6.5', '/dɪsˈeɪbld/', '/dɪsˈeɪbld/', '( the disabled ) những người tàn tật', 'having a condition that makes it difficult for you to do some things that most other people can do', 'physically/developmentally/intellectually disabled', 'khuyết tật về thể chất/phát triển/trí tuệ', '{}'::text[], ARRAY['handicapped', 'incapacitated', 'unfit', 'injured']::text[], ARRAY['enable']::text[], '{"noun": "disability", "verb": "disagree"}'::jsonb, 'disabled_uk.mp3', 'disabled_us.mp3', 'Health, Medicine & Diet', 'Healthcare System'),
  (1514, 'disadvantage', 'noun', 'b1', '5.0 - 5.5', '/ˌdɪsədˈvɑːntɪdʒ/', '/ˌdɪsədˈvæntɪdʒ/', 'sự bất lợi, thế bất lợi', 'something that causes problems and tends to stop somebody/something from succeeding or making progress', 'a serious/severe/significant disadvantage', 'một bất lợi nghiêm trọng/nghiêm trọng/đáng kể', ARRAY['a serious/severe']::text[], ARRAY['drawback', 'downside', 'handicap']::text[], ARRAY['advantage', 'benefit']::text[], '{"adjective": "disabled", "verb": "disagree"}'::jsonb, 'disadvantage_uk.mp3', 'disadvantage_us.mp3', 'Academic, Research & Abstract Concepts', 'Processes & Development'),
  (1515, 'disagree', 'verb', 'a2', '4.0 - 4.5', '/ˌdɪsəˈɡriː/', '/ˌdɪsəˈɡriː/', 'bất đồng, không đồng ý', 'if two people disagree or one person disagrees with another about something, they have a different opinion about it', 'Even friends disagree sometimes.', 'Ngay cả bạn bè đôi khi cũng không đồng ý.', ARRAY['disagree sometimes']::text[], ARRAY['differ', 'dissent', 'disaccord', 'discord']::text[], ARRAY['agree', 'concur']::text[], '{"noun": "disability", "adjective": "disabled"}'::jsonb, 'disagree_uk.mp3', 'disagree_us.mp3', 'Numbers, Measurements & Data Trends', 'Numbers & Quantity'),
