  (1747, 'email', 'verb', 'a1', '3.0 - 3.5', '/ˈiːmeɪl/', '/ˈiːmeɪl/', '@e mail', 'to send a message to somebody by email', 'email somebody, Patrick emailed me yesterday.', 'gửi email cho ai đó, Patrick đã gửi email cho tôi ngày hôm qua.', ARRAY['email somebody']::text[], ARRAY['e-mail', 'netmail', 'telecommunicate']::text[], ARRAY['snail_mail']::text[], '{}'::jsonb, 'email_uk.mp3', 'email_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
